-- Somente leitura. Criptografar o JSON com pgp_pub_encrypt ANTES de retornar os dados.
-- Não é backup integral do projeto: arquivos Storage e segredos exigem exportação própria.
WITH tabs AS (SELECT c.*,n.nspname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('solicitacoes','solicitacoes_status_historico','respostas_solicitacoes','solicitacoes_fiscalizacao_historico') AND c.relkind='r')
SELECT jsonb_build_object(
 'formato','mandato-backup-solicitacoes-producao-v1','projeto','pmmsdjozyyxkbuqlkfpb','capturado_em',now(),
 'tabelas',(SELECT jsonb_agg(jsonb_build_object('nome',t.relname,'ddl',format('CREATE TABLE public.%I (%s);',t.relname,(SELECT string_agg(format('%I %s%s%s',a.attname,format_type(a.atttypid,a.atttypmod),CASE WHEN a.attidentity='a' THEN ' GENERATED ALWAYS AS IDENTITY' WHEN a.attidentity='d' THEN ' GENERATED BY DEFAULT AS IDENTITY' WHEN d.adbin IS NOT NULL THEN ' DEFAULT '||pg_get_expr(d.adbin,d.adrelid) ELSE '' END,CASE WHEN a.attnotnull THEN ' NOT NULL' ELSE '' END),',' ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped)),
 'colunas',(SELECT jsonb_agg(attname ORDER BY attnum) FROM pg_attribute WHERE attrelid=t.oid AND attnum>0 AND NOT attisdropped),
 'dados_xml',query_to_xml(format('SELECT coalesce(jsonb_agg(to_jsonb(t)),''[]''::jsonb)::text AS dados FROM public.%I t',t.relname),true,false,''),'rls',t.relrowsecurity) ORDER BY t.relname) FROM tabs t),
 'constraints',(SELECT jsonb_agg(format('ALTER TABLE public.%I ADD CONSTRAINT %I %s;',t.relname,k.conname,pg_get_constraintdef(k.oid)) ORDER BY CASE WHEN k.contype='f' THEN 1 ELSE 0 END,k.oid) FROM pg_constraint k JOIN tabs t ON t.oid=k.conrelid WHERE k.contype IN ('p','u','c','f','x')),
 'indices',(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid)||';') FROM pg_index i JOIN tabs t ON t.oid=i.indrelid WHERE NOT EXISTS(SELECT 1 FROM pg_constraint k WHERE k.conindid=i.indexrelid)),
 'funcoes',(SELECT jsonb_agg(pg_get_functiondef(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND p.proname IN ('consulta_publica_protocolo','consulta_publica_historico_protocolo','consulta_publica_respostas_protocolo','criar_solicitacao_com_localizacao')),
 'politicas',(SELECT jsonb_agg(to_jsonb(p)) FROM pg_policies p WHERE (p.schemaname='public' AND p.tablename IN(SELECT relname FROM tabs)) OR (p.schemaname='storage' AND p.tablename='objects' AND coalesce(p.qual,p.with_check,'') NOT LIKE '%comprovantes-financeiros%')),
 'buckets',(SELECT jsonb_agg(to_jsonb(b)) FROM storage.buckets b WHERE id IN ('anexos-solicitacoes','documentos-respostas')),
 'objetos_metadata',(SELECT jsonb_agg(to_jsonb(o)) FROM storage.objects o WHERE bucket_id IN ('anexos-solicitacoes','documentos-respostas')),
 'sequencia_protocolo_xml',query_to_xml('SELECT last_value,is_called FROM public.protocolo_seq',true,false,''),
 'limites',jsonb_build_object('bytes_storage_exportados',false,'auth_exportado',false,'configuracoes_exportadas',false,'financeiro_incluido',false)
) AS backup;
